/* @lc app=leetcode id=2467 lang=kotlin */
class Solution { fun mostProfitablePath(edges: Array<IntArray>, bob: Int, amount: IntArray): Int = amount.size.let { n -> Array(n) { mutableListOf<Int>() }.also { adj -> edges.forEach { (u, v) -> adj[u].add(v).also { adj[v].add(u) } } }.let { adj -> IntArray(n) { -1 }.let { parent -> IntArray(n).let { depth -> java.util.ArrayDeque<Int>().apply { add(0) }.let { q -> generateSequence { if (q.isNotEmpty()) q.poll() else null }.forEach { u -> adj[u].forEach { v -> if (v != parent[u]) parent[v] = u.also { depth[v] = depth[u] + 1 }.also { q.add(v) } } } }.let { IntArray(n) { 1e9.toInt() }.also { bobTime -> generateSequence(bob to 0) { (u, t) -> if (parent[u] != -1) parent[u] to t + 1 else null }.forEach { (u, t) -> bobTime[u] = t } }.let { bobTime -> DeepRecursiveFunction<Triple<Int, Int, Int>, Int> { (u, p, prof) -> (if (depth[u] < bobTime[u]) amount[u] else if (depth[u] == bobTime[u]) amount[u] / 2 else 0).let { aliceGain -> (prof + aliceGain).let { curProf -> adj[u].filter { it != p }.let { children -> if (children.isEmpty()) curProf else children.maxOf { v -> callRecursive(Triple(v, u, curProf)) } } } } }.callRecursive(Triple(0, -1, 0)) } } } } } }